5	/**
6	 * The pinned region reference data used to derive an owner's locality. Knows both the
7	 * city-to-region table and each region's inclusive four-digit postcode range (NSW
8	 * 2000-2099, VIC 3000-3099, QLD 4000-4099).
9	 *
10	 * <p>Locality is derived by postcode first — {@link #localityOf(String, String)} looks up
11	 * the region whose range contains the postcode and only falls back to the city-to-region
12	 * table when the postcode is absent or in no known range. A city or postcode with no known
13	 * region resolves to {@link #UNKNOWN}.
14	 */
15	public final class CityRegion {
16	
17	    /** Locality returned when neither postcode nor city resolves to a known region. */
18	    public static final String UNKNOWN = "UNKNOWN";
19	
20	    private static final Map<String, String> CITY_TO_REGION = Map.of(
21	        "Sydney", "NSW",
22	        "Melbourne", "VIC",
23	        "Brisbane", "QLD");
24	
25	    /** Region -> inclusive {low, high} four-digit postcode range. */
26	    private static final Map<String, int[]> REGION_RANGES = Map.of(
27	        "NSW", new int[] {2000, 2099},
28	        "VIC", new int[] {3000, 3099},
29	        "QLD", new int[] {4000, 4099});
30	
31	    /** Region -> IANA timezone name. */
32	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
33	        "NSW", "Australia/Sydney",
34	        "VIC", "Australia/Melbourne",
35	        "QLD", "Australia/Brisbane");
36	
37	    private CityRegion() {
38	    }
39	
40	    /**
41	     * The canonical region for the given city, or {@link #UNKNOWN} when the city is not
42	     * in the table (including a {@code null} city).
43	     */
44	    public static String localityOf(String city) {
45	        return CITY_TO_REGION.getOrDefault(city, UNKNOWN);
46	    }
47	
48	    /**
49	     * The canonical region, preferring the postcode: the region whose pinned range
50	     * contains {@code postcode}, falling back to the {@link #localityOf(String) city
51	     * table} when the postcode is absent or in no known range. This disambiguates cities
52	     * that share a name while still resolving known cities to the same region.
53	     */
54	    public static String localityOf(String postcode, String city) {
55	        String byPostcode = regionOfPostcode(postcode);
56	        return byPostcode != null ? byPostcode : localityOf(city);
57	    }
58	
59	    /**
60	     * The region whose pinned range contains {@code postcode}, or {@code null} when the
61	     * postcode is {@code null}, not four digits, or in no known range.
62	     */
63	    public static String regionOfPostcode(String postcode) {
64	        if (postcode == null || !postcode.matches("\\d{4}")) {
65	            return null;
66	        }
67	        int value = Integer.parseInt(postcode);
68	        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
69	            int[] range = entry.getValue();
70	            if (value >= range[0] && value <= range[1]) {
71	                return entry.getKey();
72	            }
73	        }
74	        return null;
75	    }
76	
77	    /**
78	     * The IANA timezone name pinned to {@code region} (NSW -> Australia/Sydney, VIC ->
79	     * Australia/Melbourne, QLD -> Australia/Brisbane), or {@code null} when the region has
80	     * no pinned timezone (including {@link #UNKNOWN} and a {@code null} region).
81	     */
82	    public static String timezoneOf(String region) {
83	        return REGION_TIMEZONES.get(region);
84	    }
85	
86	    /**
87	     * The inclusive {low, high} four-digit postcode range pinned to {@code region}, or
88	     * {@code null} when the region has no pinned range.
89	     */
90	    public static int[] rangeOf(String region) {
91	        int[] range = REGION_RANGES.get(region);
92	        return range == null ? null : range.clone();
93	    }
94	}
